import mongoose from "mongoose";

const mobileMoneyTransactionSchema = new mongoose.Schema(
  {
    // Internal idempotency key generated by the app; not the provider's displayed reference.
    transactionId: { type: String, required: true, unique: true, trim: true },
    // Only the last six digits from the provider transaction ID are captured on the form.
    transactionIdLast6: {
      type: String,
      required: true,
      trim: true,
      match: /^\d{6}$/,
      index: true,
    },
    provider: {
      type: String,
      enum: ["AIRTEL_MONEY", "MTN_MOMO", "ZAMTEL_KWACHA", "OTHER"],
      required: true,
    },
    payerName: { type: String, required: true, trim: true },
    payerPhone: { type: String, required: true, trim: true },
    productsPurchased: { type: String, required: true, trim: true },
    productAmount: { type: Number, required: true, min: 0 },
    parcelAmount: { type: Number, required: true, min: 0 },
    totalAmount: { type: Number, required: true, min: 0 },
    status: {
      type: String,
      enum: ["RECEIVED", "REVERSED"],
      default: "RECEIVED",
      index: true,
    },
    receivedAt: { type: Date, default: Date.now, index: true },
  },
  { timestamps: true }
);

mobileMoneyTransactionSchema.index({ receivedAt: -1 });
mobileMoneyTransactionSchema.index({ provider: 1, receivedAt: -1 });
mobileMoneyTransactionSchema.index({ payerPhone: 1 });
mobileMoneyTransactionSchema.index({ status: 1, receivedAt: -1 });

const MobileMoneyTransaction =
  mongoose.models.MobileMoneyTransaction ||
  mongoose.model("MobileMoneyTransaction", mobileMoneyTransactionSchema);

export default MobileMoneyTransaction;
